// compara las lineas de pg_hba.conf contra la primera version vista
const memoria = $getWorkflowStaticData('global');
const actual = ($input.first().json.data || '').trim();
if (memoria.baselineH2 === undefined) memoria.baselineH2 = actual;
const lineas = (t) => t.split(/\r?\n/).map(l => l.trim()).filter(l => l && !l.startsWith('#'));
const base = lineas(memoria.baselineH2);
const nuevas = lineas(actual);
const agregadas = nuevas.filter(l => !base.includes(l));
const eliminadas = base.filter(l => !nuevas.includes(l));
const cambio = agregadas.length > 0 || eliminadas.length > 0;
const detalle = cambio
  ? 'Agregadas: ' + (agregadas.join(' || ') || 'ninguna') + ' | Eliminadas: ' + (eliminadas.join(' || ') || 'ninguna')
  : 'Sin cambios';
// evita repetir la alerta mientras el archivo siga igual de alterado
const nueva = cambio && detalle !== memoria.ultimoH2;
memoria.ultimoH2 = cambio ? detalle : 'SIN_CAMBIOS';
return [{ json: { alerta_h2: nueva, detalle_cambios: detalle } }];
